cat > /tmp/test_hex_parsing.go << 'EOF'
package main

import (
	"fmt"
	"image/color"
	"strconv"
	"strings"
)

// Exact copy of parseHexColor from theme/json.go
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(hex) {
	case 3:
		// RGB format (short) - each digit is duplicated
		val, err := strconv.ParseUint(hex, 16, 16)
		if err != nil {
			return nil, fmt.Errorf("invalid hex color: %w", err)
		}
		rNibble := uint8((val >> 8) & 0xF)
		gNibble := uint8((val >> 4) & 0xF)
		bNibble := uint8(val & 0xF)
		r = (rNibble << 4) | rNibble
		g = (gNibble << 4) | gNibble
		b = (bNibble << 4) | bNibble
	case 4:
		// RGBA format (short) - each digit is duplicated
		val, err := strconv.ParseUint(hex, 16, 16)
		if err != nil {
			return nil, fmt.Errorf("invalid hex color: %w", err)
		}
		rNibble := uint8((val >> 12) & 0xF)
		gNibble := uint8((val >> 8) & 0xF)
		bNibble := uint8((val >> 4) & 0xF)
		aNibble := uint8(val & 0xF)
		r = (rNibble << 4) | rNibble
		g = (gNibble << 4) | gNibble
		b = (bNibble << 4) | bNibble
		a = (aNibble << 4) | aNibble
	case 6:
		// RGB format
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return nil, fmt.Errorf("invalid hex color: %w", err)
		}
		r = uint8(val >> 16)
		g = uint8(val >> 8)
		b = uint8(val)
	case 8:
		// RGBA format
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return nil, fmt.Errorf("invalid hex color: %w", err)
		}
		r = uint8(val >> 24)
		g = uint8(val >> 16)
		b = uint8(val >> 8)
		a = uint8(val)
	default:
		return nil, fmt.Errorf("invalid hex color length: %d", len(hex))
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func testCase(name, input string, expectedR, expectedG, expectedB, expectedA uint8) {
	c, err := parseHexColor(input)
	if err != nil {
		fmt.Printf("❌ %s: ERROR: %v\n", name, err)
		return
	}

	nrgba := c.(color.NRGBA)
	if nrgba.R == expectedR && nrgba.G == expectedG && nrgba.B == expectedB && nrgba.A == expectedA {
		fmt.Printf("✅ %s: %s → R=%d G=%d B=%d A=%d\n", name, input, nrgba.R, nrgba.G, nrgba.B, nrgba.A)
	} else {
		fmt.Printf("❌ %s: %s → Got R=%d G=%d B=%d A=%d, Expected R=%d G=%d B=%d A=%d\n", 
			name, input, nrgba.R, nrgba.G, nrgba.B, nrgba.A, expectedR, expectedG, expectedB, expectedA)
	}
}

func main() {
	fmt.Println("Testing parseHexColor - All 4 Formats")
	fmt.Println("=====================================")

	// 3-digit tests (each digit duplicated)
	fmt.Println("\n3-Digit Format (RGB short):")
	testCase("3-digit #abc", "#abc", 0xaa, 0xbb, 0xcc, 0xff)
	testCase("3-digit abc", "abc", 0xaa, 0xbb, 0xcc, 0xff)
	testCase("3-digit #f00", "#f00", 0xff, 0x00, 0x00, 0xff)
	testCase("3-digit #0f0", "#0f0", 0x00, 0xff, 0x00, 0xff)
	testCase("3-digit #123", "#123", 0x11, 0x22, 0x33, 0xff)

	// 4-digit tests (each digit duplicated including alpha)
	fmt.Println("\n4-Digit Format (RGBA short):")
	testCase("4-digit #abcd", "#abcd", 0xaa, 0xbb, 0xcc, 0xdd)
	testCase("4-digit abcd", "abcd", 0xaa, 0xbb, 0xcc, 0xdd)
	testCase("4-digit #f008", "#f008", 0xff, 0x00, 0x00, 0x88)
	testCase("4-digit #0f0f", "#0f0f", 0x00, 0xff, 0x00, 0xff)
	testCase("4-digit #1234", "#1234", 0x11, 0x22, 0x33, 0x44)

	// 6-digit tests (standard RGB)
	fmt.Println("\n6-Digit Format (RGB standard):")
	testCase("6-digit #aabbcc", "#aabbcc", 0xaa, 0xbb, 0xcc, 0xff)
	testCase("6-digit aabbcc", "aabbcc", 0xaa, 0xbb, 0xcc, 0xff)
	testCase("6-digit #ff0000", "#ff0000", 0xff, 0x00, 0x00, 0xff)
	testCase("6-digit #00ff00", "#00ff00", 0x00, 0xff, 0x00, 0xff)

	// 8-digit tests (standard RGBA)
	fmt.Println("\n8-Digit Format (RGBA standard):")
	testCase("8-digit #aabbccdd", "#aabbccdd", 0xaa, 0xbb, 0xcc, 0xdd)
	testCase("8-digit aabbccdd", "aabbccdd", 0xaa, 0xbb, 0xcc, 0xdd)
	testCase("8-digit #ff000080", "#ff000080", 0xff, 0x00, 0x00, 0x80)
	testCase("8-digit #00ff00ff", "#00ff00ff", 0x00, 0xff, 0x00, 0xff)

	// Invalid formats
	fmt.Println("\nInvalid Formats (should error):")
	_, err := parseHexColor("#12")
	if err != nil {
		fmt.Printf("✅ 2-digit correctly rejected: %v\n", err)
	} else {
		fmt.Println("❌ 2-digit should have errored")
	}

	_, err = parseHexColor("#12345")
	if err != nil {
		fmt.Printf("✅ 5-digit correctly rejected: %v\n", err)
	} else {
		fmt.Println("❌ 5-digit should have errored")
	}
}
EOF
